$token = preg_replace('/[^a-fA-F0-9-]/', '', (string)($_GET['token'] ?? ''));
?><!doctype html>
<html lang="ro"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>Formular service · G-Shop</title>
<style>
:root{color-scheme:light dark;--blue:#075cff;--navy:#07152d;--bg:#f5f8fd;--card:#fff;--text:#071534;--muted:#62718a;--line:#e4eaf3;--green:#14a83b}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:Inter,ui-sans-serif,system-ui,-apple-system,sans-serif}.page{max-width:720px;margin:auto;padding:24px 16px 60px}.brand{display:flex;align-items:center;gap:12px;justify-content:center;margin:10px 0 24px}.mark{width:50px;height:50px;border-radius:15px;background:linear-gradient(145deg,#1474ff,var(--navy));display:grid;place-items:center;color:#fff;font-size:26px;font-weight:900}.brand h1{font-size:24px;margin:0}.brand p{margin:2px 0;color:var(--muted)}.hero,.card{background:var(--card);border:1px solid var(--line);border-radius:20px;padding:20px;margin-bottom:16px;box-shadow:0 10px 30px #17305a0b}.hero{background:linear-gradient(135deg,#082376,var(--blue));color:#fff}.hero p{color:#dce7ff}.card h2{font-size:18px;margin:0 0 16px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.full{grid-column:1/-1}label{display:block;font-size:13px;font-weight:750;margin-bottom:6px}input,textarea,select{width:100%;border:1px solid var(--line);background:var(--bg);color:var(--text);border-radius:12px;padding:14px;font:inherit;outline:none}input:focus,textarea:focus,select:focus{border-color:var(--blue);box-shadow:0 0 0 3px #075cff18}textarea{min-height:105px;resize:vertical}.check{display:flex;gap:10px;align-items:flex-start;margin:13px 0}.check input{width:20px;height:20px;accent-color:var(--blue)}button{width:100%;border:0;border-radius:14px;padding:16px;background:var(--blue);color:#fff;font-size:15px;font-weight:800;cursor:pointer}.status{text-align:center;padding:30px}.status .icon{font-size:48px}.hidden{display:none}.error{background:#fdecef;color:#c5263b;border-radius:12px;padding:12px;margin-bottom:14px}@media(max-width:560px){.grid{grid-template-columns:1fr}.full{grid-column:auto}.page{padding-top:12px}}@media(prefers-color-scheme:dark){:root{--bg:#040c1a;--card:#07152d;--text:#f8faff;--muted:#9cacbf;--line:#1c3657}}
</style></head><body><main class="page"><div class="brand"><div class="mark">G</div><div><h1>G-Shop</h1><p>Formular securizat de service</p></div></div><section id="loading" class="card status"><div class="icon">⌛</div><h2>Se validează linkul…</h2></section><section id="error" class="card status hidden"><div class="icon">⚠️</div><h2>Link indisponibil</h2><p id="errorText"></p></section><form id="form" class="hidden"><section class="hero"><h2 id="hello">Bună ziua!</h2><p>Completează datele necesare solicitării de service. Tokenul nu conține informații personale și este asociat numai solicitării tale.</p></section><section class="card"><h2>1. Date de contact</h2><div class="grid"><div class="full"><label>Nume și prenume *</label><input name="fullName" required minlength="3"></div><div><label>Telefon *</label><input name="phone" required inputmode="tel"></div><div><label>Email</label><input name="email" type="email"></div><div class="full"><label>Adresă completă</label><input name="address"></div><div><label>Localitate</label><input name="city" value="București"></div><div><label>Sector / județ</label><input name="county" value="București"></div></div></section><section class="card"><h2>2. Solicitare și echipament</h2><div class="grid"><div class="full"><label>Tipul solicitării</label><select name="requestType"><option>Service la domiciliu</option><option selected>Predare echipament în service</option><option>Diagnosticare</option><option>Instalare software</option><option>Configurare</option><option>Mentenanță</option><option>Altă solicitare</option></select></div><div><label>Tip echipament *</label><input name="equipmentType" required></div><div><label>Marcă</label><input name="brand"></div><div><label>Model</label><input name="model"></div><div><label>Sistem de operare</label><input name="operatingSystem"></div></div></section><section class="card"><h2>3. Problema întâmpinată</h2><div class="grid"><div class="full"><label>Descriere detaliată *</label><textarea name="problem" required minlength="10"></textarea></div><div><label>Cât de des apare?</label><input name="frequency"></div><div><label>Echipamentul pornește?</label><select name="starts"><option>Da</option><option>Nu</option><option>Uneori</option></select></div><div><label>Există date importante?</label><select name="importantData"><option>Da</option><option>Nu</option><option>Nu știu</option></select></div><div class="full"><label>Observații</label><textarea name="notes"></textarea></div></div></section><section class="card"><h2>4. Programare</h2><div class="grid"><div><label>Data preferată</label><input name="preferredDate" type="date"></div><div><label>Interval orar</label><input name="preferredInterval" placeholder="ex. 10:00–13:00"></div></div></section><section class="card"><h2>5. Consimțământ</h2><label class="check"><input type="checkbox" name="gdpr" required><span>Sunt de acord cu prelucrarea datelor în scopul furnizării serviciului.</span></label><label class="check"><input type="checkbox" name="accuracy" required><span>Confirm că informațiile completate sunt corecte.</span></label><label class="check"><input type="checkbox" name="terms" required><span>Accept condițiile de service.</span></label></section><div id="submitError" class="error hidden"></div><button id="submit" type="submit">Trimite solicitarea</button></form><section id="success" class="card status hidden"><div class="icon">✅</div><h2>Solicitarea a fost înregistrată</h2><p>Echipa de service a primit informațiile. Poți închide această pagină.</p></section></main>
<script>
const token=<?php echo json_encode($token); ?>;const base='./index.php';const loading=document.getElementById('loading'),form=document.getElementById('form'),errorBox=document.getElementById('error'),success=document.getElementById('success');
fetch(base+'/public/client-form/'+encodeURIComponent(token),{headers:{Accept:'application/json'}}).then(async r=>{const p=await r.json();if(!r.ok)throw new Error(p.message||'Link invalid.');loading.classList.add('hidden');if(p.data.used){success.querySelector('h2').textContent='Formular deja trimis';success.querySelector('p').textContent='Solicitarea a fost înregistrată. Codul QR rămâne permanent și poate fi scanat în service.';success.classList.remove('hidden');return}document.getElementById('hello').textContent='Salut, '+p.data.clientFirstName+'!';form.classList.remove('hidden')}).catch(e=>{loading.classList.add('hidden');errorBox.classList.remove('hidden');document.getElementById('errorText').textContent=e.message});
form.addEventListener('submit',async e=>{e.preventDefault();const btn=document.getElementById('submit'),err=document.getElementById('submitError');btn.disabled=true;btn.textContent='Se trimite…';err.classList.add('hidden');const data=Object.fromEntries(new FormData(form));data.gdpr=!!form.gdpr.checked;data.accuracy=!!form.accuracy.checked;data.terms=!!form.terms.checked;try{const r=await fetch(base+'/public/client-form/'+encodeURIComponent(token),{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify(data)});const p=await r.json();if(!r.ok)throw new Error(p.message||'Trimiterea a eșuat.');form.classList.add('hidden');success.classList.remove('hidden')}catch(ex){err.textContent=ex.message;err.classList.remove('hidden');btn.disabled=false;btn.textContent='Trimite solicitarea'}});
</script></body></html>
